attribute highp vec4 Position;
attribute lowp vec4 Color0;

attribute mediump vec2 TexCoord0;
varying mediump vec2 vTexCoord0;

uniform highp mat4 WorldViewProjectionMatrix;

//uniform mediump vec4 DiffuseColor;

varying lowp vec4 vColor0;

void main(void)
{
	gl_Position = WorldViewProjectionMatrix * Position;

	vColor0 = Color0;
	
	//vColor0 *= DiffuseColor;
	vTexCoord0 = TexCoord0;
}

uniform lowp sampler2D TextureSampler;
uniform lowp vec4 DiffuseColor;

varying mediump vec2 vTexCoord0;
varying lowp vec4 vColor0;

void main()
{
	lowp vec4 color = texture2D(TextureSampler, vTexCoord0) + DiffuseColor;
	color *= vColor0;

	gl_FragColor = color;
}

uniform lowp sampler2D TextureSampler;
uniform lowp vec4 DiffuseColor;

varying mediump vec2 vTexCoord0;
varying lowp vec4 vColor0;

void main()
{
	lowp vec4 color = texture2D(TextureSampler, vTexCoord0) + DiffuseColor;
	color *= vColor0;
	color.rgb *= color.a;

	gl_FragColor = color;
}
